def compute_ingested_qps(pings_per_sec=1_000_000, pings_per_batch=5, bytes_per_batch=120):
    rpc_qps = pings_per_sec // pings_per_batch
    mb_per_sec = (rpc_qps * bytes_per_batch) / (1024 * 1024)
    return {'grpc_qps': rpc_qps, 'bandwidth_mb_s': round(mb_per_sec, 2)}

def emit_segment_speed(segment_id, h3_res6, speed_kmh, sample_cnt):
    if sample_cnt >= 3:
        redis_pipe.hset(f'h3:tile:{h3_res6}', segment_id, f'{speed_kmh}:{int(time.time())}')
    clickhouse_batch.append((segment_id, h3_res6, speed_kmh, sample_cnt))

def snap_ping_local(osm_tile_cache, lat, lon, heading):
    h3_r6 = h3_encode(lat, lon, res=6)
    osm_tile = osm_tile_cache.get_or_load_mmap(h3_r6)
    candidates = osm_tile.rtree_query(lat, lon, radius_m=50)
    return viterbi_step(candidates, lat, lon, heading)

def classify_ping_timeliness(event_ts, watermark_ts, max_lateness_s=20):
    if event_ts >= watermark_ts - max_lateness_s:
        return 'LIVE_WINDOW_AND_ARCHIVE'
    return 'ARCHIVE_ONLY_LATE'

def get_traffic_tile(h3_res6_id):
    tile_data = redis_client.hgetall(f'h3:tile:{h3_res6_id}')
    if not tile_data:
        return historical_prior_tile.get(h3_res6_id)
    return tile_data

def anonymize_for_archive(ping, trip_dist_from_start_m, trip_dist_to_end_m):
    if trip_dist_from_start_m < 200 or trip_dist_to_end_m < 200:
        return None  # Strip home/work origin-destination endpoints
    ping.pop('device_id', None)
    return ping

def detect_road_incident(live_speed, hist_mean, hist_std, z_thresh=-3.0):
    z = (live_speed - hist_mean) / max(hist_std, 1.0)
    if z <= z_thresh and live_speed < 10.0:
        return 'INCIDENT_ALERT'
    return 'NORMAL'
